function nextPermutation(nums) {
  // Any larger ordering first differs at some index i, where it holds a bigger value taken from the suffix.
  // The smallest such ordering for a fixed i and value puts the remaining suffix values in ascending order.
  const compare = (a, b) => {
    for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return a[i] - b[i];
    return 0;
  };
  let best = null;
  for (let i = 0; i < nums.length; i++) {
    for (let j = i + 1; j < nums.length; j++) {
      if (nums[j] <= nums[i]) continue;
      const rest = nums.slice(i).filter((_, k) => k !== j - i).sort((a, b) => a - b);
      const candidate = [...nums.slice(0, i), nums[j], ...rest];
      if (best === null || compare(candidate, best) < 0) best = candidate;
    }
  }
  if (best === null) best = nums.slice().sort((a, b) => a - b);
  for (let i = 0; i < nums.length; i++) nums[i] = best[i];
}

